import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { ts } from "ts-morph";

// The fixture of `pin-grounds.test.mjs` and `pin-grounds.full.test.mjs`, generated by `pin-grounds.generate.mjs` (its
// header says from what, and how to regenerate it): the seven read suite files as they were when it was generated
// (`pin-grounds.frozen/`), the r3–r7 witness cases on those texts, and Codex r3's independent expected-value ranges.
// The tests read the frozen texts, never the live suites, so a re-pin on main leaves them as they were.

const fixture = JSON.parse(
  readFileSync(new URL("./pin-grounds.cases.json", import.meta.url), "utf8"),
);

/** The witness cases. */
export const cases = fixture.cases;

/** A suite file's frozen text. */
export const frozen = (file) =>
  readFileSync(
    new URL(`./pin-grounds.frozen/${file.replaceAll("/", "__")}.txt`, import.meta.url),
    "utf8",
  );

/**
 * Codex r3's expected-value positions, derived from the frozen texts by its own rule, apart from the readers: each
 * numeric literal, and each number of a `"checks …"` string, on a line of its ranges, but the declared inputs; each as
 * `[file, line, 0-based column, text]`, in source order.
 */
export function positions() {
  const found = [];
  for (const [file, ranges] of Object.entries(fixture.ranges)) {
    const source = ts.createSourceFile(file, frozen(file), ts.ScriptTarget.Latest, true);
    const visit = (node) => {
      const { line: zero, character } = source.getLineAndCharacterOfPosition(node.getStart(source));
      const line = zero + 1;
      if (ranges.some(([from, to]) => from <= line && line <= to)) {
        const text = node.getText(source);
        if (ts.isNumericLiteral(node)) {
          if (
            !fixture.inputs.some(
              ([inFile, inLine, inText]) => inFile === file && inLine === line && inText === text,
            )
          )
            found.push([file, line, character, text]);
        } else if (ts.isStringLiteral(node) && /^checks \d/u.test(node.text))
          for (const number of text.matchAll(/\d[\d_]*/gu))
            found.push([file, line, character + number.index, number[0]]);
      }
      ts.forEachChild(node, visit);
    };
    visit(source);
  }
  return found;
}

/** `text` with a `git diff -U0` applied: each removed line must be the text's. */
export function apply(text, diff) {
  const lines = text.split("\n");
  const out = [];
  let cursor = 0;
  for (const hunk of diff.split(/^(?=@@ )/mu).filter((part) => part.startsWith("@@"))) {
    const [header, ...body] = hunk.replace(/\n$/u, "").split("\n");
    const [, from, count] = /^@@ -(\d+)(?:,(\d+))? /u.exec(header);
    const start = count === "0" ? Number(from) : Number(from) - 1;
    out.push(...lines.slice(cursor, start));
    cursor = start;
    for (const line of body)
      if (line.startsWith("-")) {
        assert.equal(lines[cursor], line.slice(1), `removed line ${cursor + 1}`);
        cursor += 1;
      } else if (line.startsWith("+")) out.push(line.slice(1));
  }
  out.push(...lines.slice(cursor));
  return out.join("\n");
}

/** `text` with the number at a position moved by one. */
export function moved(text, [, line, column, value]) {
  const lines = text.split("\n");
  const at = lines[line - 1];
  lines[line - 1] =
    `${at.slice(0, column)}${Number(value.replaceAll("_", "")) + 1}${at.slice(column + value.length)}`;
  return lines.join("\n");
}
